-- RID=217 | MENU=3 | ITEM=1 | RQUERY=1 | NAME=Daftar Formula Produksi (BOM) | FILE=ListBillOfMaterial
SELECT bom.bomnotransaksi, bom.bomtgl, k.knama AS bompembuat, bomuraian, pc.pcnama AS bomjenis, st.nama AS bomstatus , bom.bomid FROM m6_bom bom JOIN m1_production_category pc ON bom.bomjenis = pc.pckode JOIN m0_status st on bom.bomstatus = st.kode LEFT JOIN m1_contact k ON bom.bompembuat = k.kid ORDER BY bom.bomtgl, bom.bomid, bom.bomnotransaksi;

