-- RID=344 | MENU=3 | ITEM=4 | RQUERY=1 | NAME=Daftar Formula Produksi (BOM) Per Produk | FILE=ListBillOfMaterial_perproduk[CB]
SELECT bid, bkode, namabarang , bomstatus , bomtgl, bomnotransaksi, bominputuser, knama, kkode FROM (SELECT b.bid, b.bkode, bomin.namabarang , bom.bomstatus , bom.bomtgl, bom.bomnotransaksi, bom.bominputuser, k.knama, kkode FROM m6_bom_in bomin JOIN m6_bom bom ON bomin.idbom = bom.bomid JOIN m1_item b ON bomin.idbarang = b.bid JOIN m1_contact k ON bom.bompembuat = k.kid UNION SELECT bb.bid, bb.bkode , bomout.namabarang , bom.bomstatus , bom.bomtgl, bom.bomnotransaksi, bom.bominputuser, k.knama, kkode FROM m6_bom_out bomout JOIN m6_bom bom ON bomout.idbom = bom.bomid JOIN m1_item bb ON bomout.idbarang = bb.bid JOIN m1_contact k ON bom.bompembuat = k.kid ) as a GROUP BY bid, bkode , namabarang ORDER BY bid, bkode , namabarang;

