-- RID=1608 | MENU=3 | ITEM=10 | RQUERY=1 | NAME=Daftar Formula Produksi (BOM) | FILE=-
SELECT bomid, bomnotransaksi, bomtgl, b.btipe, bomin.idbarang as idhasil, b.bkode as kodehasil, bomin.namabarang, bomout.idbarang as idbahan, bbahan.bkode as kodebahan, bomout.namabarang, bomin.jml as jmljadi,bomout.jml as jmlbahan, 100-(bomin.jml/bomout.jml*100) AS persentasesusut FROM m6_bom bom JOIN (select * from m6_bom_in GROUP BY idbomin) AS bomin ON bomin.idbom = bom.bomid join m1_item b ON b.bid = bomin.idbarang JOIN (SELECT * from m6_bom_out WHERE jml > 0 GROUP BY idbom) AS bomout ON bomid = bomout.idbom join m1_item bbahan ON bbahan.bid = bomout.idbarang GROUP BY bom.bomid ORDER BY bom.bomtgl, bom.bomid, bom.bomnotransaksi;

