SELECT bom.bomid , bom.bomnotransaksi , bom.bomuraian , b.bkode , b.bnama , bomin.jml , bomin.satuan , bb.bkode AS kodebarang , bb.bnama AS namabarang , bomout.jml AS jumlah , bomout.satuan AS sat FROM m6_bom bom JOIN m6_bom_in bomin ON bom.bomid = bomin.idbom JOIN m1_item b ON bomin.idbarang = b.bid JOIN m6_bom_out bomout ON bom.bomid = bomout.idbom JOIN m1_item bb ON bomout.idbarang = bb.bid ORDER BY bom.bomtgl ASC , bom.bomid ASC , bom.bomnotransaksi ASC;

