SELECT bid, bkode, namabarang, kkode, pdrnotransaksi, pdrtgl FROM (SELECT b.bid, b.bkode , pdrin.namabarang , k.kkode, pdr.pdrnotransaksi, pdr.pdrtgl FROM m6_pdr_in pdrin JOIN m1_item b ON pdrin.idbarang = b.bid JOIN m6_pdr pdr ON pdrin.idpdr = pdr.pdrid JOIN m1_contact k ON pdr.pdrdimintaoleh UNION SELECT b.bid , b.bkode , pdrout.namabarang , k.kkode, pdr.pdrnotransaksi, pdr.pdrtgl FROM m6_pdr_out pdrout JOIN m1_item b ON pdrout.idbarang = b.bid JOIN m6_pdr pdr ON pdrout.idpdr = pdr.pdrid JOIN m1_contact k ON pdr.pdrdimintaoleh ) as a GROUP BY bid, bkode , namabarang ORDER BY bid, bkode , namabarang;

