-- RID=50003779 | MENU=4 | ITEM=14 | RQUERY=1 | NAME=Machine Production Planning | FILE=MachineProductionPlanning
SELECT p.*, @zsaldo := CASE WHEN @zmesin = p.mesin AND @ztgl = p.tgl THEN @zsaldo - p.jmlpd ELSE p.kapasitasmesin - p.jmlpd END as zsaldo, @zmesin := p.mesin as zmesin, @ztgl := p.tgl as ztgl FROM (SELECT idmsmq, mesin, tgl, kapasitasmesin, idpdrin, pdrnotransaksi, pdrtgl, pdrtgldipakai, kkode, knama, idsodetail, sonotransaksi, sotgl, sotglkirim, idbarang, bkode, namabarang, bkelasproduk, kapasitasperhari, jmlbarang, backorder, jmlpd, satuanbarang, idlogin, userid FROM m2r_machinepdplanning ORDER BY mesin ASC, tgl ASC, bkode ASC, sotglkirim ASC, jmlpd DESC, idpdrin ASC) as p , (SELECT @ztgl := "") as VariableInit1 , (SELECT @zsaldo := 0) as VariableInit2 , (SELECT @zmesin := "") as VariableInit3;

