-- RID=263 | MENU=5 | ITEM=5 | RQUERY=1 | NAME=Daftar WO terkait MRS dan MRN | FILE=WOMRSMRN
SELECT wo.woid , wo.wonotransaksi FROM m6_wo wo LEFT JOIN m1_contact ks ON wo.womintake = ks.kid LEFT JOIN m1_contact kc ON wo.wodimintaoleh = kc.kid LEFT JOIN m1_production_category pc ON wo.wojenis = pc.pckode left JOIN m1_warehouse wa ON wo.wogudangasal = wa.wkode LEFT JOIN m1_warehouse wp ON wo.wogudangproduksi = wp.wkode LEFT JOIN m1_warehouse wt ON wo.wogudangtujuan = wt.wkode ORDER BY wo.woid;

-- RID=264 | MENU=5 | ITEM=6 | RQUERY=1 | NAME=Daftar WO terkait MRS dan PD | FILE=WOMRSPD
SELECT wo.woid , wo.wonotransaksi FROM m6_wo wo LEFT JOIN m1_contact ks ON wo.womintake = ks.kid LEFT JOIN m1_contact kc ON wo.wodimintaoleh = kc.kid LEFT JOIN m1_production_category pc ON wo.wojenis = pc.pckode left JOIN m1_warehouse wa ON wo.wogudangasal = wa.wkode LEFT JOIN m1_warehouse wp ON wo.wogudangproduksi = wp.wkode LEFT JOIN m1_warehouse wt ON wo.wogudangtujuan = wt.wkode ORDER BY wo.woid;

-- RID=267 | MENU=5 | ITEM=7 | RQUERY=1 | NAME=Daftar Perintah Kerja (WO) Outstanding Sisa | FILE=WOOutstandingSIsa
SELECT /* WO (WO>MRS>MRN>PD)*/ wo.wonotransaksi , wo.woid , wo.wotgl, ks.knama AS womintake , kc.knama AS wodimintaoleh , wo.wocatatan , CASE wo.wostatus WHEN 0 THEN "Draft" WHEN 1 THEN "Minta Approve" WHEN 2 THEN "Approved" WHEN 3 THEN "Inprogress" WHEN 4 THEN "Complete" WHEN 5 THEN "Revisi" WHEN 6 THEN "Reject" WHEN 7 THEN "Close" WHEN 8 THEN "Approve 1" WHEN 9 THEN "Approve 2" WHEN 10 THEN "Approve 3" WHEN 11 THEN "Approve 4" WHEN 12 THEN "Hapus" END AS wostatus FROM m6_wo wo JOIN m1_contact ks ON wo.womintake = ks.kid JOIN m1_contact kc ON wo.wodimintaoleh = kc.kid ORDER BY wo.woid;

