-- RID=275 | MENU=6 | ITEM=8 | RQUERY=1 | NAME=Daftar Pengeluaran Bahan Baku (MRS) Outstanding Sisa | FILE=MRSOutstandingSisa
SELECT /*MRS(MRS>MRN>PD)*/ mrs.mrsnotransaksi , mrs.mrsid , mrs.mrstgl , ks.knama AS mrsbagianmrs , mrs.mrscatatan , CASE mrs.mrsstatus WHEN 0 THEN "Draft" WHEN 1 THEN "Minta Approve" WHEN 2 THEN "Approved" WHEN 3 THEN "Inprogress" WHEN 4 THEN "Complete" WHEN 5 THEN "Revisi" WHEN 6 THEN "Reject" WHEN 7 THEN "Close" WHEN 8 THEN "Approve 1" WHEN 9 THEN "Approve 2" WHEN 10 THEN "Approve 3" WHEN 11 THEN "Approve 4" WHEN 12 THEN "Hapus" END AS mrsstatus FROM m6_mrs mrs LEFT JOIN m1_contact ks on mrs.mrsbagianmrs = ks.kid LEFT JOIN m1_production_category pc ON mrs.mrsjenis = pc.pckode ORDER BY mrs.mrsid;

