-- RID=50000567 | MENU=8 | ITEM=15 | RQUERY=1 | NAME=Laporan Jasa Produksi Per Transaksi | FILE=jasa_produksi_pertransaksi
SELECT pd.pdid , pd.pdnotransaksi , pdo.idbarang, b.bkode , b.bnama , pdo.jml, pdo.satuan , pdo.harga , (pdo.jml * pdo.harga) AS total FROM m6_pd pd JOIN m6_pd_out pdo ON pd.pdid = pdo.idpd JOIN m1_item b ON pdo.idbarang = b.bid WHERE b.bjenis = "J" ORDER BY pd.pdtgl ASC , pd.pdnotransaksi ASC , pdo.urutan ASC;

-- RID=50000568 | MENU=8 | ITEM=16 | RQUERY=1 | NAME=Laporan Jasa Produksi Per Tanggal | FILE=jasa_produksi_rekap_pertgl
SELECT pd.pdid , pd.pdnotransaksi , pd.pdtgl , pdo.idbarang, b.bkode , b.bnama , SUM(pdo.jml) AS jml, pdo.satuan , pdo.harga , Sum(pdo.jml * pdo.harga) AS total FROM m6_pd pd JOIN m6_pd_out pdo ON pd.pdid = pdo.idpd JOIN m1_item b ON pdo.idbarang = b.bid WHERE b.bjenis = "J" GROUP BY pdo.idbarang ASC , pd.pdtgl ASC ORDER BY pdo.idbarang ASC , pd.pdtgl ASC;

-- RID=50000577 | MENU=8 | ITEM=17 | RQUERY=1 | NAME=Laporan Hasil Produksi | FILE=hasil_produksi2
SELECT pd.pduraian , pd.pdcatatan , pd.pdid , pdi.urutan , b.bnama AS namabarang , pdi.jmlbarang , pdi.satuanbarang, pd.pdtgl , pdi.hpp , (SELECT SUM(pdo.jmlbarang) AS jmlbarang FROM m6_pd_out pdo JOIN m6_pd pdd ON pdo.idpd = pdd.pdid WHERE pd.pduraian = pdd.pduraian GROUP BY pdd.pduraian ORDER BY pdd.pduraian ASC ) AS a FROM m6_pd pd JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd JOIN m1_item b ON pdi.idbarang = b.bid ORDER BY pd.pdcatatan ASC , pd.pdtgl ASC , pd.pdnotransaksi ASC , pd.pdid ASC , pdi.urutan ASC , pdi.idpdin ASC;

-- RID=50001630 | MENU=8 | ITEM=19 | RQUERY=1 | NAME=Standart dan Realisasi Pemakaian Bahan | FILE=Standart dan Realisasi Pemakaian Bahan
SELECT pd.pdid , pd.pdnotransaksi , pd.pdtgl, pd.pdtgldipakai, pc.pcnama AS pdjenis , pd.pduraian , st.nama AS pdstatus FROM m6_pd pd JOIN m1_production_category pc ON pd.pdjenis = pc.pckode JOIN m0_status st ON pd.pdstatus = st.kode ORDER BY pd.pdtgl , pd.pdid , pd.pdnotransaksi;

-- RID=50001761 | MENU=8 | ITEM=20 | RQUERY=1 | NAME=Laporan Produksi Per Produk | FILE=pd_perbarang_jadi
SELECT b.bkode, b.bnama , pd.pdtgl , pd.pdnotransaksi , pdin.jml , pdin.satuan FROM m6_pd pd JOIN m6_pd_in pdin ON pd.pdid = pdin.idpd JOIN m1_item b ON pdin.idbarang = b.bid WHERE pd.pdstatus IN (2,3,4,7) ORDER BY b.bkode ASC , b.bnama ASC , pd.pdtgl ASC , pd.pdnotransaksi ASC;

-- RID=50003807 | MENU=8 | ITEM=21 | RQUERY=1 | NAME=Production Backorder Report Global | FILE=pd_backorderglobal
SELECT c.kkode, c.knama, so.soid, so.sonotransaksi, so.sotgl, so.sotglkirim, sod.idbarang, sod.jmlbarang, sod.satuan, pdp.mesin, pdp.tgl, MIN(pdp.tgl) as prodstartdate, MAX(pdp.tgl) as prodcompletedate, pdp.customtext10, SUM(CASE WHEN pd.pdcustomtext2 <> 'FG' THEN pdi.jmlbarang ELSE 0 END) as jmlpdwip, SUM(CASE pd.pdcustomtext2 WHEN 'FG' THEN pdi.jmlbarang ELSE 0 END) as jmlpdfg, sod.jmlbarang - SUM(CASE WHEN pd.pdcustomtext2 <> 'FG' THEN pdi.jmlbarang ELSE 0 END) as bowip, sod.jmlbarang - SUM(CASE pd.pdcustomtext2 WHEN 'FG' THEN pdi.jmlbarang ELSE 0 END) as bofg, c.kcatatan, i.bsatuan, i.bkode, i.bnama, i.bkelasproduk, cp.cpnama as bkelasproduknama, IFNULL(dttgl.jmlplan,0) as jmlplan, sod.jmlbarang - IFNULL(dttgl.jmlplan,0) as blmplan FROM m5_so so JOIN m1_contact c ON so.socustomer = c.kid JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid JOIN m5_so_production sod ON so.soid = sod.idso AND so.sostatus IN(2,3) JOIN m1_item i ON sod.idbarang = i.bid JOIN (SELECT idso, idbarang, SUM(jmlbarang - jmlrealisasi) as sisa FROM m5_so_detail GROUP BY idso, idbarang HAVING sisa > 0) as sodet ON sod.idso = sodet.idso AND sod.idbarang = sodet.idbarang LEFT JOIN m6_production_planning pdp ON so.soid = pdp.idsodetail AND sod.idbarang = pdp.idbarang LEFT JOIN m6_pd pd ON pdp.customtext10 = pd.pdcustomtext1 AND pd.pdstatus IN(2,3,4,7) LEFT JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid LEFT JOIN m1_class_product cp ON i.bkelasproduk = cp.cpkode LEFT JOIN (SELECT idsodetail, idbarang, max(tgl) as maxtgl, min(tgl) as mintgl, SUM(jmlbarang) as jmlplan FROM m6_production_planning GROUP BY idsodetail, idbarang ) as dttgl ON so.soid = dttgl.idsodetail AND sod.idbarang = dttgl.idbarang GROUP BY c.kkode, so.sotgl, so.soid, i.bkode ORDER BY c.kkode, so.sotgl, so.soid, i.bkode;

-- RID=50003808 | MENU=8 | ITEM=22 | RQUERY=1 | NAME=Production Backorder Report Detail | FILE=pd_backorderdetail
SELECT c.kkode, c.knama, c.kcatatan, so.soid, so.sonotransaksi, so.sotgl, so.sotglkirim, sod.idbarang, i.bkode, i.bnama, i.bsatuan, sod.jmlbarang, sod.satuan, pdp.mesin, pdp.tgl, dttgl.mintgl as prodstardate, dttgl.maxtgl as prodcompletedate, pdp.jml, pdp.customtext10 as routecard, SUM(CASE WHEN pd.pdcustomtext2 <> 'FG' THEN pdi.jmlbarang ELSE 0 END) as jmlpdwip, SUM(CASE pd.pdcustomtext2 WHEN 'FG' THEN pdi.jmlbarang ELSE 0 END) as jmlpdfg, pdp.jml - SUM(CASE WHEN pd.pdcustomtext2 <> 'FG' THEN pdi.jmlbarang ELSE 0 END) as bowip, pdp.jml - SUM(CASE pd.pdcustomtext2 WHEN 'FG' THEN pdi.jmlbarang ELSE 0 END) as bofg, IFNULL(dttgl.jmlplan,0) as jmlplan, sod.jmlbarang - IFNULL(dttgl.jmlplan,0) as blmplan FROM m5_so so JOIN m1_contact c ON so.socustomer = c.kid JOIN m5_so_production sod ON so.soid = sod.idso AND so.sostatus IN(2,3) JOIN m1_item i ON sod.idbarang = i.bid JOIN (SELECT idso, idbarang, SUM(jmlbarang - jmlrealisasi) as sisa FROM m5_so_detail GROUP BY idso, idbarang HAVING sisa > 0) as sodet ON sod.idso = sodet.idso AND sod.idbarang = sodet.idbarang LEFT JOIN m6_production_planning pdp ON so.soid = pdp.idsodetail AND sod.idbarang = pdp.idbarang LEFT JOIN m6_pd pd ON pdp.customtext10 = pd.pdcustomtext1 AND pd.pdstatus IN(2,3,4,7) LEFT JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd LEFT JOIN (SELECT idsodetail, idbarang, max(tgl) as maxtgl, min(tgl) as mintgl, SUM(jmlbarang) as jmlplan FROM m6_production_planning GROUP BY idsodetail, idbarang ) as dttgl ON so.soid = dttgl.idsodetail AND sod.idbarang = dttgl.idbarang GROUP BY c.kkode, so.sotgl, so.soid, i.bkode, pdp.idpdpdetail ORDER BY c.kkode, so.sotgl, so.soid, i.bkode, pdp.idpdpdetail;

-- RID=50003809 | MENU=8 | ITEM=23 | RQUERY=1 | NAME=Daily Production Report | FILE=pd_dailyreport
SELECT c.kkode, IFNULL(c.knama, pd.pdcustomtext4) as knama, c.kcatatan, so.soid, IFNULL(so.sonotransaksi,pd.pdnoref) as sonotransaksi, so.sotgl, so.sotglkirim, sod.idbarang, i.bkode as kodebarangSO, i.bnama as namabarangSO, i.bsatuan as satuanbarangSO, sod.jmlbarang as jmlso, sod.satuan as satuanso, pdp.mesin as pdpmesin, pdp.tgl as pdptgl, dttgl.mintgl as pdpstartdate, dttgl.maxtgl as pdpcompletedate, pdp.jml as pdpjml, IFNULL(pdp.customtext10, pd.pdcustomtext1) as pdproutecard, pd.pdtgl AS pdtgl, pd.pdnotransaksi AS pdnotransaksi, pd.pdcustomtext2 AS pdjenis, pd.pdcustomtext1 as pdroutecard, pd.pdcustomtext3 as tungku, ip.bid AS pdidbarang, ip.bkode AS pdkodebarang, ip.bnama AS pdnamabarang, pdi.jmlbarang as pdjml, pdout.jmlbarang as jmlbahan, ROUND(100 - (pdi.jmlbarang / pdout.jmlbarang* 100), 5) AS persentasesusut FROM m6_pd pd JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd AND pd.pdstatus IN(2,3,4,7) JOIN m1_item ip ON pdi.idbarang = ip.bid JOIN m6_pd_out pdout ON pd.pdid = pdout.idpd AND pdout.jmlbarang > 0 JOIN m1_item ib ON pdout.idbarang = ib.bid AND ib.bjenis = 'P' LEFT JOIN m6_production_planning pdp ON pd.pdcustomtext1 = pdp.customtext10 LEFT JOIN m5_so_production sod ON pdp.idsodetail = sod.idso AND pdp.idbarang = sod.idbarang LEFT JOIN m5_so so ON sod.idso = so.soid LEFT JOIN m1_contact c ON so.socustomer = c.kid LEFT JOIN m1_item i ON sod.idbarang = i.bid LEFT JOIN (SELECT idsodetail, idbarang, max(tgl) as maxtgl, min(tgl) as mintgl FROM m6_production_planning GROUP BY idsodetail, idbarang ) as dttgl ON so.soid = dttgl.idsodetail AND sod.idbarang = dttgl.idbarang GROUP BY pd.pdcustomtext3, pd.pdtgl, pd.pdnotransaksi, c.kkode, so.sotgl, i.bkode, pdp.idpdpdetail, pd.pdid, pdi.idpdin ORDER BY pd.pdcustomtext3, pd.pdtgl, pd.pdnotransaksi, c.kkode, so.sotgl, i.bkode, pdp.idpdpdetail, pd.pdid, pdi.idpdin;

-- RID=50003811 | MENU=8 | ITEM=24 | RQUERY=2 | NAME=Laporan Abu | FILE=Laporan_Abu
SELECT * FROM m2r_abunew ORDER BY tanggal DESC;

-- RID=50003820 | MENU=8 | ITEM=25 | RQUERY=2 | NAME=Production Backorder Report Detail | FILE=pd_backorderdetailnew
SELECT bo.idlogin, bo.kkode, bo.knama, bo.kcatatan, bo.soid, bo.sonotransaksi, bo.sotgl, bo.sotglkirim, bo.idbarang, bo.bkode, bo.bnama, bo.bsatuan, bo.jmlbarang, bo.satuan, bo.mesin, bo.tgl, bo.prodstardate, bo.prodcompletedate, bo.jml, bo.routecard, bo.jmlpdwip, bo.jmlpdfg, bo.bowip, bo.bofg, bo.jmlplan, bo.blmplan, bo.idmsmq, bo.userid FROM m2r_bo_production bo ORDER BY bo.kkode, bo.sotgl, bo.soid, bo.bkode, bo.tgl, bo.routecard;

-- RID=50003821 | MENU=8 | ITEM=26 | RQUERY=2 | NAME=Production Backorder Report Global | FILE=pd_backorderglobalnew
SELECT bo.idlogin, bo.kkode, bo.knama, bo.kcatatan, bo.soid, bo.sonotransaksi, bo.sotgl, bo.sotglkirim, bo.idbarang, bo.bkode, bo.bnama, bo.bsatuan, bo.jmlbarang, bo.satuan, bo.mesin, bo.tgl, bo.prodstardate as prodstartdate, bo.prodcompletedate, SUM(bo.jml) as jml, bo.routecard, SUM(bo.jmlpdwip) as jmlpdwip, SUM(bo.jmlpdfg) as jmlpdfg, (bo.bowip) as bowip, (bo.bofg) as bofg, bo.jmlplan, bo.blmplan, bo.idmsmq, bo.userid, i.bkelasproduk FROM m2r_bo_production_global bo JOIN m1_item i ON bo.idbarang = i.bid GROUP BY bo.kkode, bo.sotgl, bo.soid, bo.bkode ORDER BY bo.kkode, bo.sotgl, bo.soid, bo.bkode;

-- RID=50003830 | MENU=8 | ITEM=27 | RQUERY=1 | NAME=Daftar Produksi (PD) | FILE=-
SELECT pd.pdid , pd.pdnotransaksi , pd.pdtgl, wo.wonotransaksi, pd.pdtgldipakai, pc.pcnama AS pdjenis , pd.pduraian , st.nama AS pdstatus, b.bkode as kodehasil, pdin.namabarang as namahasil, pdin.jmlbarang as jmlhasil, pdin.satuanbarang as satuanhasil, pdin.customdbl1 as jmlbatang, pdin.hpppersen, pdin.hpp as hargahasil, (pdin.jmlbarang * pdin.hpp) as totalhasil, b2.bkode as kodebahan, pdout.namabarang as namabahan, pdout.jmlbarang as jmlbahan, pdout.satuanbarang as satuanbahan, pdout.hpp as hargabahan, (pdout.jmlbarang * pdout.hpp) as totalbahan FROM m6_pd pd JOIN m1_production_category pc ON pd.pdjenis = pc.pckode JOIN m0_status st ON pd.pdstatus = st.kode JOIN m6_pd_in pdin ON pd.pdid = pdin.idpd JOIN m1_item b ON pdin.idbarang = b.bid JOIN m6_pd_out pdout ON pd.pdid = pdout.idpd JOIN m1_item b2 ON pdout.idbarang = b2.bid LEFT JOIN m6_wo wo ON pd.pdidwo = wo.woid ORDER BY pd.pdtgl , pd.pdid , pd.pdnotransaksi, pdin.urutan, pdin.idpdin, pdout.urutan, pdout.idpdout;

-- RID=1604 | MENU=25 | ITEM=1 | RQUERY=2 | NAME=Stok Cover Day | FILE=StokCoverDay_2
SELECT * FROM m2r_stok_coverday ORDER BY scidbarang;

-- RID=1611 | MENU=25 | ITEM=2 | RQUERY=2 | NAME=Stok Cover Day | FILE=StokCoverDay_2
SELECT * FROM m2r_stok_coverday ORDER BY scidbarang;

-- RID=1668 | MENU=26 | ITEM=1 | RQUERY=1 | NAME=Laporan Produksi Dan Penjualan Dalam Berat Ton | FILE=produksidanpenjualan_dlmton
SELECT it.tgl , it.idbarang , b.bkode , b.bnama, CASE it.sumber WHEN "PD" THEN "Produksi" WHEN "SI" THEN "Penjualan" END AS sumber , it.jenismutasi , IFNULL(SUM(it.jmlbarang * b.baberat) / 1000,0) as jmlbarang , YEAR(it.tgl) as tahun , MONTH(it.tgl) as bulan FROM m1_item_transaction it JOIN m1_item b ON it.idbarang = b.bid WHERE ((it.sumber = "PD" AND it.jenismutasi = 1) OR (it.sumber = "SI" AND it.jenismutasi = 0 )) GROUP BY it.idbarang ASC, it.sumber ASC, MONTH(it.tgl) ASC ORDER BY it.idbarang ASC, it.sumber ASC, MONTH(it.tgl) ASC;

-- RID=2001 | MENU=26 | ITEM=2 | RQUERY=2 | NAME=Laporan Produksi VS Penjualan VS Stok | FILE=produksivspenjualanvsstok
SELECT pvp.idlogin, pvp.pvptahun, pvp.pvpidbarang, CONCAT(i.bnamaalias1, '') as pvpkodebarang, pvp.pvpurutan, pvp.pvpketerangan, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpjan WHEN pvp.pvptahun = YEAR(NOW()) AND 1 <= MONTH(NOW()) THEN pvp.pvpjan ELSE 0 END) as pvpjan, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpfeb WHEN pvp.pvptahun = YEAR(NOW()) AND 2 <= MONTH(NOW()) THEN pvp.pvpfeb ELSE 0 END) as pvpfeb, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpmar WHEN pvp.pvptahun = YEAR(NOW()) AND 3 <= MONTH(NOW()) THEN pvp.pvpmar ELSE 0 END) as pvpmar, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpapr WHEN pvp.pvptahun = YEAR(NOW()) AND 4 <= MONTH(NOW()) THEN pvp.pvpapr ELSE 0 END) as pvpapr, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpmei WHEN pvp.pvptahun = YEAR(NOW()) AND 5 <= MONTH(NOW()) THEN pvp.pvpmei ELSE 0 END) as pvpmei, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpjun WHEN pvp.pvptahun = YEAR(NOW()) AND 6 <= MONTH(NOW()) THEN pvp.pvpjun ELSE 0 END) as pvpjun, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpjul WHEN pvp.pvptahun = YEAR(NOW()) AND 7 <= MONTH(NOW()) THEN pvp.pvpjul ELSE 0 END) as pvpjul, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpagu WHEN pvp.pvptahun = YEAR(NOW()) AND 8 <= MONTH(NOW()) THEN pvp.pvpagu ELSE 0 END) as pvpagu, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpsep WHEN pvp.pvptahun = YEAR(NOW()) AND 9 <= MONTH(NOW()) THEN pvp.pvpsep ELSE 0 END) as pvpsep, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpokt WHEN pvp.pvptahun = YEAR(NOW()) AND 10 <= MONTH(NOW()) THEN pvp.pvpokt ELSE 0 END) as pvpokt, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpnov WHEN pvp.pvptahun = YEAR(NOW()) AND 11 <= MONTH(NOW()) THEN pvp.pvpnov ELSE 0 END) as pvpnov, (CASE WHEN pvp.pvptahun < YEAR(NOW()) THEN pvp.pvpdes WHEN pvp.pvptahun = YEAR(NOW()) AND 12 <= MONTH(NOW()) THEN pvp.pvpdes ELSE 0 END) as pvpdes, pvp.idmsmq, pvp.pvpuserid FROM M2r_Produksi_Vs_Penjualan pvp JOIN m1_item i ON pvp.pvpidbarang = i.bid ORDER BY pvp.pvpkodebarang, pvp.pvpurutan;

-- RID=50003799 | MENU=90 | ITEM=1 | RQUERY=1 | NAME=Machine Plotting | FILE=MachinePlotting
SELECT mp.mesin, m.mnama, mp.tgl, mp.kelas, c.cnama, mp.subkelas, sc.scnama, sc.sccatatan FROM m6_machine_plotting mp JOIN m1_machine m ON mp.mesin = m.mkode JOIN m1_class c ON mp.kelas = c.ckode JOIN m1_subclass sc ON mp.subkelas = sc.sckode ORDER BY mp.mesin, mp.tgl, mp.kelas, mp.subkelas;

-- RID=50003797 | MENU=91 | ITEM=1 | RQUERY=1 | NAME=Daily Production Plan and Realization Per Machine | FILE=pdp_machine
SELECT pp.mesin, m.mnama AS mesinnama, pp.tgl, pp.kelas, cl.cnama AS kelasnama, pp.subkelas, sc.scnama AS subkelasnama, pp.customtext10 AS norc, so.sonotransaksi, so.sotgl, so.sotglkirim, so.socustomer, c.kkode AS socustomerkode, c.knama AS socustomernama, i.bkode, i.bnama, pp.jml, CEIL(pp.jml/i.bjmllapangan) as jmlpcs, pp.satuan, pp.jmljam, i.baoem AS kadar, i.baukuran AS ukuran, i.bapanjang AS panjang, IFNULL(pd.jmlbarang,0) as jmlbr1, IFNULL(pd.customdbl1,0) as jmlpcsbr1, IFNULL(fg.jmlbarang,0) + IFNULL(fs.jmlbarang,0) as jmlfg, IFNULL(fg.customdbl1,0) + IFNULL(fs.customdbl1,0) as jmlpcsfg, 0 as jmlfs, 0 as jmlpcsfs FROM m6_production_planning pp JOIN m1_machine m ON pp.mesin = m.mkode JOIN m1_class cl ON pp.kelas = cl.ckode JOIN m1_subclass sc ON pp.subkelas = sc.sckode JOIN m1_item i ON pp.idbarang = i.bid LEFT JOIN m5_so so ON pp.idsodetail = so.soid LEFT JOIN m1_contact c ON so.socustomer = c.kid LEFT JOIN (SELECT pd.pdcustomtext1, pdi.jmlbarang, pdi.customdbl1 FROM m6_pd pd JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd AND pd.pdstatus IN(2,3,4,7) AND pd.pdcustomtext2 = 'WIP1' ) as pd ON pp.customtext10 = pd.pdcustomtext1 LEFT JOIN (SELECT pd.pdcustomtext1, pdi.jmlbarang, pdi.customdbl1 FROM m6_pd pd JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd AND pd.pdstatus IN(2,3,4,7) AND pd.pdcustomtext2 = 'FG' ) as fg ON pp.customtext10 = fg.pdcustomtext1 LEFT JOIN (SELECT pd.pdcustomtext1, pdi.jmlbarang, pdi.customdbl1 FROM m6_pd pd JOIN m6_pd_in pdi ON pd.pdid = pdi.idpd AND pd.pdstatus IN(2,3,4,7) AND pd.pdcustomtext2 = 'FS' ) as fs ON pp.customtext10 = fs.pdcustomtext1 GROUP BY pp.mesin, pp.tgl, pp.urutan, pp.kelas, pp.subkelas, so.sonotransaksi, i.bkode, pp.idplan ORDER BY pp.mesin, pp.tgl, pp.urutan, pp.kelas, pp.subkelas, so.sonotransaksi, i.bkode;

-- RID=50003798 | MENU=91 | ITEM=2 | RQUERY=1 | NAME=Route Card | FILE=pdp_routecard
SELECT pp.mesin, m.mnama AS mesinnama, pp.tgl, pp.kelas, cl.cnama AS kelasnama, pp.subkelas, sc.scnama AS subkelasnama, pp.customtext10 AS norc, so.sonotransaksi, so.sotgl, so.sotglkirim, so.socustomer, c.kkode AS socustomerkode, c.knama AS socustomernama, i.bkode, i.bnama, pp.jml, CEIL(pp.jml/i.bjmllapangan) as jmlpcs, pp.satuan, pp.jmljam, i.baoem AS kadar, i.baukuran AS ukuran, i.bapanjang AS panjang, i.bamodel as model, i.bavolume as volume, i.bnamaalias5 FROM m6_production_planning pp JOIN m1_machine m ON pp.mesin = m.mkode JOIN m1_class cl ON pp.kelas = cl.ckode JOIN m1_subclass sc ON pp.subkelas = sc.sckode JOIN m1_item i ON pp.idbarang = i.bid LEFT JOIN m5_so so ON pp.idsodetail = so.soid LEFT JOIN m1_contact c ON so.socustomer = c.kid ORDER BY pp.mesin, pp.tgl, pp.urutan, pp.kelas, pp.subkelas, so.sonotransaksi, i.bkode;

-- RID=50003818 | MENU=91 | ITEM=3 | RQUERY=1 | NAME=Route Card | FILE=pdp_routecard_BW1
SELECT pp.mesin, m.mnama AS mesinnama, pp.tgl, pp.kelas, cl.cnama AS kelasnama, pp.subkelas, sc.scnama AS subkelasnama, pp.customtext10 AS norc, so.sonotransaksi, so.sotgl, so.sotglkirim, so.socustomer, c.kkode AS socustomerkode, c.knama AS socustomernama, i.bkode, i.bnama, pp.jml, CEIL(pp.jml/i.bjmllapangan) as jmlpcs, pp.satuan, pp.jmljam, i.baoem AS kadar, i.baukuran AS ukuran, i.bapanjang AS panjang, i.bamodel as model, i.bavolume as volume FROM m6_production_planning pp JOIN m1_machine m ON pp.mesin = m.mkode JOIN m1_class cl ON pp.kelas = cl.ckode JOIN m1_subclass sc ON pp.subkelas = sc.sckode JOIN m1_item i ON pp.idbarang = i.bid LEFT JOIN m5_so so ON pp.idsodetail = so.soid LEFT JOIN m1_contact c ON so.socustomer = c.kid ORDER BY pp.mesin, pp.tgl, pp.urutan, pp.kelas, pp.subkelas, so.sonotransaksi, i.bkode;

-- RID=50003819 | MENU=91 | ITEM=4 | RQUERY=1 | NAME=Route Card | FILE=pdp_routecard_BW2
SELECT pp.mesin, m.mnama AS mesinnama, pp.tgl, pp.kelas, cl.cnama AS kelasnama, pp.subkelas, sc.scnama AS subkelasnama, pp.customtext10 AS norc, so.sonotransaksi, so.sotgl, so.sotglkirim, so.socustomer, c.kkode AS socustomerkode, c.knama AS socustomernama, i.bkode, i.bnama, pp.jml, CEIL(pp.jml/i.bjmllapangan) as jmlpcs, pp.satuan, pp.jmljam, i.baoem AS kadar, i.baukuran AS ukuran, i.bapanjang AS panjang, i.bamodel as model, i.bavolume as volume FROM m6_production_planning pp JOIN m1_machine m ON pp.mesin = m.mkode JOIN m1_class cl ON pp.kelas = cl.ckode JOIN m1_subclass sc ON pp.subkelas = sc.sckode JOIN m1_item i ON pp.idbarang = i.bid LEFT JOIN m5_so so ON pp.idsodetail = so.soid LEFT JOIN m1_contact c ON so.socustomer = c.kid ORDER BY pp.mesin, pp.tgl, pp.urutan, pp.kelas, pp.subkelas, so.sonotransaksi, i.bkode;

